'use client';

import { Canvas } from '@react-three/fiber';
import { Stars, OrbitControls } from '@react-three/drei';
import { Suspense } from 'react';
import Tower from './Tower';
import CameraRig from './CameraRig';

// TEMP: flip to false (or delete this + the <OrbitControls> block below)
// once the CameraRig waypoints are locked in. While true, CameraRig is
// disabled since both would fight over the camera every frame. Also read
// by app/page.tsx to let mouse events pass through the HTML overlay to
// the canvas so OrbitControls can actually receive drags.
export const DEBUG_ORBIT_CONTROLS = true;

function TowerFallback() {
  return (
    <mesh>
      <boxGeometry args={[40, 200, 40]} />
      <meshBasicMaterial color="#ff00ff" wireframe />
    </mesh>
  );
}

export default function Scene({ scrollProgress }: { scrollProgress: React.MutableRefObject<number> }) {
  return (
    <Canvas
      shadows
      dpr={[1, 2]}
      gl={{ antialias: true }}
      camera={{ fov: 45, near: 0.1, far: 2000, position: [500, 380, 550] }}
      style={{ position: 'fixed', inset: 0 }}
    >
      <color attach="background" args={['#05050a']} />
      {/* far bumped from 500 -> 1400: the t=0/t=1 wide establishing shots sit
          ~800-900 units from the tower, plus its ~289-unit bounding-sphere
          radius, so the old far=500 fogged the whole building into the
          background color at those waypoints. */}
      <fog attach="fog" args={['#05050a', 200, 1400]} />

      <ambientLight intensity={0.6} />
      <directionalLight
        position={[100, 200, 100]}
        intensity={1.4}
        color="#fff2d8"
        castShadow
      />
      <directionalLight position={[-100, 80, -100]} intensity={0.6} color="#4a6a8a" />
      <hemisphereLight args={['#8899bb', '#05050a', 0.5]} />

      <Suspense fallback={<TowerFallback />}>
        <Tower />
      </Suspense>

      <Stars radius={300} depth={80} count={2000} factor={4} saturation={0} fade speed={0.5} />

      {DEBUG_ORBIT_CONTROLS ? (
        <OrbitControls makeDefault target={[0, 90, 0]} />
      ) : (
        <CameraRig scrollProgress={scrollProgress} />
      )}
    </Canvas>
  );
}
